describe('Browser Push Notification for Urgent Alerts', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display push notification when urgent alert is received', () => {
    // Mock push notification API
    cy.intercept('POST', '/api/notifications/urgent').as('urgentNotification');

    // Trigger urgent notification
    cy.get('[data-testid="send-urgent-alert-btn"]').click();

    // Wait for the notification API call
    cy.wait('@urgentNotification');

    // Verify notification is displayed
    cy.get('[data-testid="notification-container"]').should('be.visible');
    cy.get('[data-testid="notification-title"]').should('contain', 'Urgent Alert');
    cy.get('[data-testid="notification-body"]').should('contain', 'This is an urgent alert');

    // Verify notification icon is visible
    cy.get('[data-testid="notification-icon"]').should('be.visible');

    // Verify notification badge count
    cy.get('[data-testid="notification-badge"]').should('contain', '1');

    // Verify notification dismiss button is present
    cy.get('[data-testid="notification-dismiss-btn"]').should('be.visible');

    // Verify notification is dismissible
    cy.get('[data-testid="notification-dismiss-btn"]').click();

    // Verify notification disappears
    cy.get('[data-testid="notification-container"]').should('not.exist');
  });

  it('should handle multiple urgent notifications and display count', () => {
    // Mock multiple urgent notifications
    cy.intercept('POST', '/api/notifications/urgent', {
      statusCode: 200,
      body: {
        message: 'First urgent alert',
        priority: 'high'
      }
    }).as('firstUrgentNotification');

    cy.intercept('POST', '/api/notifications/urgent', {
      statusCode: 200,
      body: {
        message: 'Second urgent alert',
        priority: 'high'
      }
    }).as('secondUrgentNotification');

    // Trigger first urgent notification
    cy.get('[data-testid="send-urgent-alert-btn"]').click();
    cy.wait('@firstUrgentNotification');

    // Trigger second urgent notification
    cy.get('[data-testid="send-urgent-alert-btn"]').click();
    cy.wait('@secondUrgentNotification');

    // Verify notification count is updated
    cy.get('[data-testid="notification-badge"]').should('contain', '2');

    // Verify notification list is displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');

    // Verify notifications are listed with titles
    cy.get('[data-testid="notification-item"]').should('have.length', 2);
    cy.get('[data-testid="notification-item"]').first().should('contain', 'First urgent alert');
    cy.get('[data-testid="notification-item"]').eq(1).should('contain', 'Second urgent alert');

    // Verify notification dismiss button is present for each item
    cy.get('[data-testid="notification-item"]').first().should('have.descendant', '[data-testid="notification-dismiss-btn"]');
    cy.get('[data-testid="notification-item"]').eq(1).should('have.descendant', '[data-testid="notification-dismiss-btn"]');

    // Verify dismissing a notification updates the count
    cy.get('[data-testid="notification-item"]').first().click();
    cy.get('[data-testid="notification-badge"]').should('contain', '1');
  });
});
